 24→@Service
 25→@ConditionalOnProperty(name = ["legacy-sync.enabled"], havingValue = "true", matchIfMissing = false)
 26→class LegacyReserveSyncApplicationService(
 27→    private val legacyReserveSyncRepository: LegacyReserveSyncRepository,
 28→    private val cachedProxyApplicationService: CachedProxyApplicationService,
 29→) {
 30→    private val logger by logger()
 31→
 32→    fun syncToLegacy(changedData: List<ChangedData<LegacyProductData>>) {
 33→        if (changedData.isEmpty()) return
 34→
 35→        val dependencyId = getDependencyId(changedData)
 36→        val dependency = cachedProxyApplicationService.fetchDependencies(dependencyId)
 37→
 38→        runBlocking(Dispatchers.IO) {
 39→            // push 태스크 수집 → supervisorScope로 병렬 실행 (개별 실패 격리)
 40→            val pushTasks = buildPushTasks(changedData, dependency.categories, dependency.malls)
 41→
 42→            if (pushTasks.isNotEmpty()) {
 43→                supervisorScope {
 44→                    pushTasks
 45→                        .map { task ->
 46→                            async {
 47→                                runCatching { task() }
 48→                                    .onFailure { ex -> logger.error(ex) { "Legacy push 실패" } }
 49→                            }
 50→                        }.awaitAll()
 51→                }
 52→            }
 53→        }
 54→    }
 55→
 56→    private fun buildPushTasks(
 57→        changedData: List<ChangedData<LegacyProductData>>,
 58→        categories: Map<Int, CategoryProjection>,
 59→        malls: Map<Int, MallProjection>,
 60→    ): List<suspend () -> Unit> {
 61→        val pushTasks = mutableListOf<suspend () -> Unit>()
 62→        val grouped = changedData.groupBy { it.op }
 63→
 64→        grouped.forEach { (op, items) ->
 65→            val linked = mutableListOf<LinkedProductRequest>()
 66→            val unlinked = mutableListOf<UnlinkedProductRequest>()
 67→            val unlinkedDeletes = mutableListOf<UnlinkedProductDeleteRequest>()
 68→
 69→            items.forEach items@{ item ->
 70→                val data = if (op == Operation.DELETE) item.beforeData else item.afterData
 71→                if (data == null) {
 72→                    logger.warn { "Legacy sync skipped: no data for product id=${item.id}, op=$op" }
 73→                    return@items
 74→                }
 75→
 76→                val mall = malls[data.shopId]
 77→
 78→                when {
 79→                    data.isCatalogMatch -> {
 80→                        linked.add(LegacySyncMapper.convertToLinkedRequest(data, mall))
 81→                    }
 82→
 83→                    op == Operation.DELETE -> {
 84→                        unlinkedDeletes.add(LegacySyncMapper.convertToUnlinkedDeleteRequest(data, mall))
 85→                    }
 86→
 87→                    else -> {
 88→                        val category = categories[data.categoryId]
 89→                        unlinked.add(LegacySyncMapper.convertToUnlinkedRequest(data, category, mall))
 90→                    }
 91→                }
 92→            }
 93→
 94→            if (linked.isNotEmpty()) pushTasks.add { legacyReserveSyncRepository.pushLinkedProducts(linked, op) }
 95→            if (unlinked.isNotEmpty()) pushTasks.add { legacyReserveSyncRepository.pushUnlinkedProducts(unlinked, op) }
 96→            if (unlinkedDeletes.isNotEmpty()) {
 97→                pushTasks.add {
 98→                    legacyReserveSyncRepository.pushUnlinkedProductDeletes(
 99→                        unlinkedDeletes,
100→                    )
101→                }
102→            }
103→        }
104→
105→        return pushTasks
106→    }
107→
108→    fun getDependencyId(documents: List<ChangedData<LegacyProductData>>): DependencyId {
109→        val categoryIds: MutableList<Int> = mutableListOf()
110→        val mallIds: MutableList<Int> = mutableListOf()
111→
112→        documents.forEach {
113→            it.afterData?.categoryId?.run { categoryIds.add(this) }
114→            it.afterData?.shopId?.run { mallIds.add(this) }
115→        }
116→
117→        return DependencyId(
118→            categoryIds = categoryIds.distinct(),
119→            mallIds = mallIds.distinct(),
120→        )
121→    }
122→}
